cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

RWTexture2D<float4> output : register(u0);

float hash(float2 p)
{
    return frac(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

[numthreads(8, 8, 1)]
void CSMain(uint3 dtid : SV_DispatchThreadID)
{
    uint2 dim;
    output.GetDimensions(dim.x, dim.y);
    if (dtid.x >= dim.x || dtid.y >= dim.y)
        return;

    int2 pos = int2(dtid.xy);

    if (frame_index == 0) {
        float r = hash(float2(pos) + float2(0.5, 0.5));
        float alive = r > 0.6 ? 1.0 : 0.0;
        output[pos] = float4(alive, alive, alive, 1.0);
        return;
    }

    int neighbors = 0;
    for (int dy = -1; dy <= 1; dy++) {
        for (int dx = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) continue;
            int2 np = (pos + int2(dx, dy) + int2(dim)) % int2(dim);
            float4 nc = output[np];
            if (nc.r > 0.5) neighbors++;
        }
    }

    float4 current = output[pos];
    bool alive = current.r > 0.5;
    bool nextAlive = alive ? (neighbors == 2 || neighbors == 3) : (neighbors == 3);

    float3 color = float3(0, 0, 0);
    if (nextAlive) {
        float t = frac(time_sim_ms * 0.0003);
        color = float3(0.2 + 0.8 * t, 0.8 - 0.3 * t, 0.4);
    }
    output[pos] = float4(color, 1.0);
}
